// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address anyAddr) public {
        // The reference contract's owner() returns the deployer (address(this)), not zero.
        // We call addReward to exercise the internal updateReward modifier, but the property
        // is about owner() itself, independent of fuzz parameters.
        vm.assume(anyAddr != address(0));
        c.addReward(anyAddr);
        assertTrue(c.owner() != address(0));
    }
}

